-- estacion
create table public.estacion (
  id bigint primary key not null,
  codigo character varying(5) not null,
  nombre character varying(100) not null,
  entidad_federativa character varying(40) not null,
  tipo character varying(30) not null,
  capacidad_teu_dia integer,
  ubicacion geography(Point,4326) not null,
  constraint estacion_capacidad_chk check ((tipo in ('puerto_maritimo', 'terminal_intermodal')) = (capacidad_teu_dia is not null) and (capacidad_teu_dia is null or capacidad_teu_dia > 0)),
  constraint estacion_codigo_formato_chk check (codigo ~ '^[A-Z]{3,5}$'),
  constraint estacion_tipo_chk check (tipo in ('puerto_maritimo', 'terminal_intermodal', 'patio_clasificacion', 'cruce_fronterizo', 'estacion_paso'))
);
create unique index estacion_codigo_key on estacion using btree (codigo);

-- tramo
create table public.tramo (
  id bigint primary key not null,
  codigo character varying(12) not null,
  linea character varying(3) not null,
  estacion_origen_id bigint not null,
  estacion_destino_id bigint not null,
  kilometraje_oficial_km numeric(7,2) not null,
  numero_vias smallint not null,
  velocidad_maxima_kmh smallint not null,
  carga_max_eje_ton numeric(4,1) not null,
  pendiente_gobernante_pct numeric(4,2) not null,
  traza geography(LineString,4326) not null,
  foreign key (estacion_origen_id) references public.estacion (id)
  match simple on update no action on delete no action,
  foreign key (estacion_destino_id) references public.estacion (id)
  match simple on update no action on delete no action,
  constraint tramo_carga_eje_chk check (carga_max_eje_ton between 20 and 40),
  constraint tramo_extremos_distintos_chk check (estacion_origen_id <> estacion_destino_id),
  constraint tramo_kilometraje_chk check (kilometraje_oficial_km > 0),
  constraint tramo_numero_vias_chk check (numero_vias in (1, 2)),
  constraint tramo_pendiente_chk check (pendiente_gobernante_pct between 0 and 5),
  constraint tramo_velocidad_chk check (velocidad_maxima_kmh between 10 and 120)
);
create unique index tramo_codigo_key on tramo using btree (codigo);
create unique index tramo_extremos_key on tramo using btree (estacion_origen_id, estacion_destino_id);
create index tramo_estacion_destino_id on tramo using btree (estacion_destino_id);
create index tramo_estacion_origen_id on tramo using btree (estacion_origen_id);

-- geocerca
create table public.geocerca (
  id bigint primary key not null,
  codigo character varying(20) not null,
  nombre character varying(120) not null,
  tipo character varying(30) not null,
  estacion_id bigint,
  velocidad_maxima_kmh smallint,
  prohibe_materiales_peligrosos boolean not null,
  vigencia daterange not null,
  perimetro geography(MultiPolygon,4326) not null,
  foreign key (estacion_id) references public.estacion (id)
  match simple on update no action on delete no action,
  constraint geocerca_estacion_chk check ((tipo in ('patio_ferroviario', 'recinto_fiscal')) = (estacion_id is not null)),
  constraint geocerca_tipo_chk check (tipo in ('patio_ferroviario', 'recinto_fiscal', 'zona_urbana', 'area_natural_protegida')),
  constraint geocerca_velocidad_chk check (velocidad_maxima_kmh is null or velocidad_maxima_kmh between 5 and 80),
  constraint geocerca_vigencia_chk check (isempty(vigencia) = false and lower_inf(vigencia) = false)
);
create unique index geocerca_codigo_key on geocerca using btree (codigo);
create index geocerca_estacion_id on geocerca using btree (estacion_id);

-- locomotora
create table public.locomotora (
  id bigint primary key not null,
  numero_economico character varying(10) not null,
  modelo character varying(30) not null,
  potencia_hp integer not null,
  peso_ton numeric(5,1) not null,
  anio_fabricacion smallint not null,
  estatus character varying(10) not null,
  constraint locomotora_anio_chk check (anio_fabricacion between 1970 and 2026),
  constraint locomotora_estatus_chk check (estatus in ('activa', 'taller', 'baja')),
  constraint locomotora_peso_chk check (peso_ton between 100 and 220),
  constraint locomotora_potencia_chk check (potencia_hp between 1000 and 6000)
);
create unique index locomotora_numero_economico_key on locomotora using btree (numero_economico);

-- carro
create table public.carro (
  id bigint primary key not null,
  marca_reporte character varying(4) not null,
  numero integer not null,
  tipo character varying(30) not null,
  tara_ton numeric(5,1) not null,
  peso_bruto_max_ton numeric(5,1) not null,
  longitud_m numeric(5,2) not null,
  num_ejes smallint not null,
  constraint carro_longitud_chk check (longitud_m between 10 and 40),
  constraint carro_marca_formato_chk check (marca_reporte ~ '^[A-Z]{2,4}$'),
  constraint carro_num_ejes_chk check (num_ejes in (4, 6, 8, 10)),
  constraint carro_numero_chk check (numero between 1 and 999999),
  constraint carro_pesos_chk check (tara_ton > 0 and tara_ton < peso_bruto_max_ton),
  constraint carro_tipo_chk check (tipo in ('furgon', 'tolva_cubierta', 'gondola', 'tanque', 'plataforma_doble_estiba', 'autorack'))
);
create unique index carro_marca_numero_key on carro using btree (marca_reporte, numero);

-- cliente
create table public.cliente (
  id bigint primary key not null,
  rfc character varying(13) not null,
  razon_social character varying(150) not null,
  sector character varying(30) not null,
  planta geography(Point,4326) not null,
  constraint cliente_rfc_formato_chk check (rfc ~ '^[A-ZÑ&]{3,4}[0-9]{6}[A-Z0-9]{3}$'),
  constraint cliente_sector_chk check (sector in ('agroindustria', 'automotriz', 'siderurgia', 'quimica', 'energia', 'construccion', 'mineria', 'comercio'))
);
create unique index cliente_rfc_key on cliente using btree (rfc);

-- embarque
create table public.embarque (
  id bigint primary key not null,
  folio character varying(20) not null,
  remitente_id bigint not null,
  destinatario_id bigint not null,
  estacion_origen_id bigint not null,
  estacion_destino_id bigint not null,
  documentado_en timestamp with time zone not null,
  clase_mercancia character varying(30) not null,
  descripcion_mercancia character varying(120) not null,
  numero_onu character(6),
  contenedor character(11),
  peso_neto_ton numeric(7,2) not null,
  valor_declarado_mxn numeric(14,2) not null,
  detalle jsonb not null,
  foreign key (remitente_id) references public.cliente (id)
  match simple on update no action on delete no action,
  foreign key (destinatario_id) references public.cliente (id)
  match simple on update no action on delete no action,
  foreign key (estacion_origen_id) references public.estacion (id)
  match simple on update no action on delete no action,
  foreign key (estacion_destino_id) references public.estacion (id)
  match simple on update no action on delete no action,
  constraint embarque_clase_chk check (clase_mercancia in ('granos', 'automotriz', 'acero', 'quimicos', 'combustibles', 'cemento', 'minerales', 'carga_contenerizada')),
  constraint embarque_contenedor_chk check ((clase_mercancia = 'carga_contenerizada') = (contenedor is not null) and (contenedor is null or case when (contenedor ~ '^[A-Z]{3}[UJZ][0-9]{7}$') then mod(mod(((ascii(substr(contenedor, 1, 1)) - 55) + (ascii(substr(contenedor, 1, 1)) - 56) / 10) * 1 + ((ascii(substr(contenedor, 2, 1)) - 55) + (ascii(substr(contenedor, 2, 1)) - 56) / 10) * 2 + ((ascii(substr(contenedor, 3, 1)) - 55) + (ascii(substr(contenedor, 3, 1)) - 56) / 10) * 4 + ((ascii(substr(contenedor, 4, 1)) - 55) + (ascii(substr(contenedor, 4, 1)) - 56) / 10) * 8 + cast(substr(contenedor, 5, 1) as integer) * 16 + cast(substr(contenedor, 6, 1) as integer) * 32 + cast(substr(contenedor, 7, 1) as integer) * 64 + cast(substr(contenedor, 8, 1) as integer) * 128 + cast(substr(contenedor, 9, 1) as integer) * 256 + cast(substr(contenedor, 10, 1) as integer) * 512, 11), 10) = cast(right(contenedor, 1) as integer) else false end)),
  constraint embarque_detalle_objeto_chk check (jsonb_typeof(detalle) = 'object'),
  constraint embarque_estaciones_distintas_chk check (estacion_origen_id <> estacion_destino_id),
  constraint embarque_numero_onu_chk check (numero_onu is null or numero_onu ~ '^UN[0-9]{4}$'),
  constraint embarque_partes_distintas_chk check (remitente_id <> destinatario_id),
  constraint embarque_peso_chk check (peso_neto_ton > 0),
  constraint embarque_valor_chk check (valor_declarado_mxn >= 0)
);
create unique index embarque_folio_key on embarque using btree (folio);
create index embarque_destinatario_id on embarque using btree (destinatario_id);
create index embarque_estacion_destino_id on embarque using btree (estacion_destino_id);
create index embarque_estacion_origen_id on embarque using btree (estacion_origen_id);
create index embarque_remitente_id on embarque using btree (remitente_id);

-- tren
create table public.tren (
  id bigint primary key not null,
  simbolo character varying(12) not null,
  fecha_servicio date not null,
  estacion_origen_id bigint not null,
  estacion_destino_id bigint not null,
  salida_programada timestamp with time zone not null,
  salida_real timestamp with time zone,
  llegada_real timestamp with time zone,
  estado character varying(12) not null,
  foreign key (estacion_origen_id) references public.estacion (id)
  match simple on update no action on delete no action,
  foreign key (estacion_destino_id) references public.estacion (id)
  match simple on update no action on delete no action,
  constraint tren_estaciones_distintas_chk check (estacion_origen_id <> estacion_destino_id),
  constraint tren_estado_chk check (estado in ('programado', 'en_ruta', 'arribado', 'cancelado')),
  constraint tren_estado_tiempos_chk check (estado in ('programado', 'cancelado') and salida_real is null and llegada_real is null or estado = 'en_ruta' and salida_real is not null and llegada_real is null or estado = 'arribado' and salida_real is not null and llegada_real is not null),
  constraint tren_tiempos_chk check (llegada_real is null or salida_real is not null and llegada_real > salida_real)
);
create unique index tren_simbolo_fecha_key on tren using btree (simbolo, fecha_servicio);
create index tren_estacion_destino_id on tren using btree (estacion_destino_id);
create index tren_estacion_origen_id on tren using btree (estacion_origen_id);

-- itinerario
create table public.itinerario (
  tren_id bigint not null,
  secuencia smallint not null,
  tramo_id bigint not null,
  sentido character varying(7) not null,
  primary key (tren_id, secuencia),
  foreign key (tren_id) references public.tren (id)
  match simple on update no action on delete no action,
  foreign key (tramo_id) references public.tramo (id)
  match simple on update no action on delete no action,
  constraint itinerario_secuencia_chk check (secuencia >= 1),
  constraint itinerario_sentido_chk check (sentido in ('directo', 'inverso'))
);
create unique index itinerario_tren_tramo_key on itinerario using btree (tren_id, tramo_id);
create index itinerario_tramo_id on itinerario using btree (tramo_id);

-- composicion
create table public.composicion (
  tren_id bigint not null,
  posicion smallint not null,
  locomotora_id bigint,
  carro_id bigint,
  embarque_id bigint,
  primary key (tren_id, posicion),
  foreign key (tren_id) references public.tren (id)
  match simple on update no action on delete no action,
  foreign key (locomotora_id) references public.locomotora (id)
  match simple on update no action on delete no action,
  foreign key (carro_id) references public.carro (id)
  match simple on update no action on delete no action,
  foreign key (embarque_id) references public.embarque (id)
  match simple on update no action on delete no action,
  constraint composicion_cabeza_locomotora_chk check (posicion <> 1 or locomotora_id is not null),
  constraint composicion_carga_en_carro_chk check (embarque_id is null or carro_id is not null),
  constraint composicion_posicion_chk check (posicion >= 1),
  constraint composicion_vehiculo_unico_chk check (num_nonnulls(locomotora_id, carro_id) = 1)
);
create unique index composicion_tren_carro_key on composicion using btree (tren_id, carro_id);
create unique index composicion_tren_embarque_key on composicion using btree (tren_id, embarque_id);
create unique index composicion_tren_locomotora_key on composicion using btree (tren_id, locomotora_id);
create index composicion_carro_id on composicion using btree (carro_id);
create index composicion_embarque_id on composicion using btree (embarque_id);
create index composicion_locomotora_id on composicion using btree (locomotora_id);

-- telemetria
create table public.telemetria (
  id bigint primary key not null,
  tren_id bigint not null,
  registrado_en timestamp with time zone not null,
  posicion geography(Point,4326) not null,
  velocidad_kmh numeric(5,1) not null,
  rumbo_grados numeric(4,1) not null,
  presion_freno_psi numeric(4,1) not null,
  foreign key (tren_id) references public.tren (id)
  match simple on update no action on delete no action,
  constraint telemetria_presion_chk check (presion_freno_psi between 0 and 110),
  constraint telemetria_rumbo_chk check (rumbo_grados >= 0 and rumbo_grados < 360),
  constraint telemetria_velocidad_chk check (velocidad_kmh between 0 and 130)
);
create unique index telemetria_tren_instante_key on telemetria using btree (tren_id, registrado_en);

